/* Intermediate 1 · ShopKaro egress, endpoint and two-sided routing. */
(function () {
  const N=AG.aws.n;
  const table=(s,id)=>(s.account.routeTables||[]).find(t=>t.id===id);
  const route=(s,id,dest,target)=>{const t=table(s,id);return !!t&&(t.routes||[]).some(r=>r.destination===dest&&r.target===target&&r.state!=='blackhole');};
  const associated=(s,rt,sub)=>!!table(s,rt)&&(table(s,rt).associations||[]).some(a=>a.subnetId===sub);
  function seed(){
    const specs=[['public-a','10.9.1.0/24','a'],['public-b','10.9.2.0/24','b'],['app-a','10.9.11.0/24','a'],['app-b','10.9.12.0/24','b'],['orders','10.9.21.0/24','a']];
    return {region:'ap-south-1',vpcs:[{id:'vpc-shop',cidr:'10.9.0.0/16',name:'ShopKaro',dnsSupport:true,dnsHostnames:true},{id:'vpc-analytics',cidr:'10.10.0.0/16',name:'Analytics',dnsSupport:true,dnsHostnames:true}],
      subnets:[...specs.map(([name,cidr,az])=>({id:'subnet-'+name,vpcId:'vpc-shop',cidr,az:'ap-south-1'+az,public:false})),{id:'subnet-analytics',vpcId:'vpc-analytics',cidr:'10.10.1.0/24',az:'ap-south-1a',public:false}],
      internetGateways:[{id:'igw-shop',vpcId:'vpc-shop'}],
      routeTables:[...specs.map(([name])=>({id:'rtb-'+name,vpcId:'vpc-shop',routes:[{destination:'10.9.0.0/16',target:'local',type:'local'},...(name.startsWith('public')?[{destination:'0.0.0.0/0',target:'igw-shop',type:'igw'}]:[])],associations:[{id:'rtbassoc-'+name,subnetId:'subnet-'+name}]})),{id:'rtb-analytics',vpcId:'vpc-analytics',routes:[{destination:'10.10.0.0/16',target:'local',type:'local'}],associations:[{id:'rtbassoc-analytics',subnetId:'subnet-analytics'}]}],
      securityGroups:[{id:'sg-app',vpcId:'vpc-shop',name:'app',ingress:[],egress:[{protocol:'tcp',fromPort:443,toPort:443,cidr:'0.0.0.0/0'}]},{id:'sg-orders',vpcId:'vpc-shop',name:'orders-reader',ingress:[{protocol:'tcp',fromPort:5432,toPort:5432,cidr:'10.10.1.0/24'}]}],
      instances:[{id:'i-app-a',name:'app-a',state:'running',vpcId:'vpc-shop',subnetId:'subnet-app-a',az:'ap-south-1a',privateIp:'10.9.11.10',publicIp:null,sgIds:['sg-app']},{id:'i-app-b',name:'app-b',state:'running',vpcId:'vpc-shop',subnetId:'subnet-app-b',az:'ap-south-1b',privateIp:'10.9.12.10',publicIp:null,sgIds:['sg-app']}],
      rds:[{id:'orders-read',name:'orders-reader',engine:'postgres',class:'db.t3.small',state:'available',source:'orders-main',encrypted:true,publicAccess:false,endpoint:'orders-read.sim.ap-south-1.rds.amazonaws.com',storage:20}],
      buckets:[{name:'shop-flowlogs',encryption:true,public:false,objects:[]}],addresses:[],natGateways:[],vpcEndpoints:[],vpcPeerings:[],flowLogs:[],
    };
  }
  function natOK(s,az){
    const n=(s.account.natGateways||[]).find(n=>n.subnetId==='subnet-public-'+az&&n.state==='available'&&n.connectivityType==='public');
    return !!n&&associated(s,'rtb-public-'+az,'subnet-public-'+az)&&associated(s,'rtb-app-'+az,'subnet-app-'+az)&&route(s,'rtb-public-'+az,'0.0.0.0/0','igw-shop')&&route(s,'rtb-app-'+az,'0.0.0.0/0',n.id)&&(s.account.addresses||[]).some(a=>a.allocationId===n.allocationId&&a.natId===n.id);
  }
  function endpointOK(s){
    return (s.account.vpcEndpoints||[]).some(e=>e.type==='Gateway'&&e.serviceName==='com.amazonaws.ap-south-1.s3'&&e.vpcId==='vpc-shop'&&e.state==='available'&&['a','b'].every(az=>(e.routeTableIds||[]).includes('rtb-app-'+az)&&!!table(s,'rtb-app-'+az)&&(table(s,'rtb-app-'+az).routes||[]).some(r=>r.prefixListId===e.prefixListId&&r.target===e.id&&r.state!=='blackhole')));
  }
  function peerOK(s){return (s.account.vpcPeerings||[]).some(p=>p.state==='active'&&[p.requester,p.accepter].includes('vpc-shop')&&[p.requester,p.accepter].includes('vpc-analytics')&&route(s,'rtb-orders','10.10.0.0/16',p.id)&&route(s,'rtb-analytics','10.9.0.0/16',p.id)&&associated(s,'rtb-orders','subnet-orders')&&associated(s,'rtb-analytics','subnet-analytics'));}
  function preserved(s){
    const d=(s.account.rds||[]).find(r=>r.id==='orders-read'),g=(s.account.securityGroups||[]).find(g=>g.id==='sg-orders'),app=(s.account.securityGroups||[]).find(g=>g.id==='sg-app');
    return !!app&&app.ingress.length===0&&app.egress.length===1&&app.egress[0].protocol==='tcp'&&app.egress[0].fromPort===443&&app.egress[0].toPort===443&&app.egress[0].cidr==='0.0.0.0/0'&&!!d&&d.state==='available'&&d.encrypted&&!d.publicAccess&&!!g&&g.ingress.length===1&&g.ingress[0].protocol==='tcp'&&g.ingress[0].fromPort===5432&&g.ingress[0].toPort===5432&&g.ingress[0].cidr==='10.10.1.0/24'&&['a','b'].every(az=>(s.account.instances||[]).some(i=>i.id==='i-app-'+az&&i.state==='running'&&!i.publicIp&&i.subnetId==='subnet-app-'+az))&&(s.account.routeTables||[]).length===6&&(s.account.routeTables||[]).every(t=>t.routes.some(r=>r.target==='local'))&&(s.account.internetGateways||[]).some(g=>g.id==='igw-shop'&&g.vpcId==='vpc-shop');
  }
  const SOLUTION=[
    'aws ec2 allocate-address --domain vpc',
    'aws ec2 allocate-address --domain vpc',
    'aws ec2 create-nat-gateway --subnet-id subnet-public-a --allocation-id eipalloc-000000001',
    'aws ec2 wait nat-gateway-available --nat-gateway-ids nat-000000001',
    'aws ec2 create-nat-gateway --subnet-id subnet-public-b --allocation-id eipalloc-000000002',
    'aws ec2 wait nat-gateway-available --nat-gateway-ids nat-000000002',
    'aws ec2 create-route --route-table-id rtb-app-a --destination-cidr-block 0.0.0.0/0 --nat-gateway-id nat-000000001',
    'aws ec2 create-route --route-table-id rtb-app-b --destination-cidr-block 0.0.0.0/0 --nat-gateway-id nat-000000002',
    'aws ec2 create-vpc-endpoint --vpc-id vpc-shop --vpc-endpoint-type Gateway --service-name com.amazonaws.ap-south-1.s3 --route-table-ids rtb-app-a rtb-app-b',
    'aws ec2 create-vpc-peering-connection --vpc-id vpc-shop --peer-vpc-id vpc-analytics',
    'aws ec2 accept-vpc-peering-connection --vpc-peering-connection-id pcx-000000001',
    'aws ec2 create-route --route-table-id rtb-orders --destination-cidr-block 10.10.0.0/16 --vpc-peering-connection-id pcx-000000001',
    'aws ec2 create-route --route-table-id rtb-analytics --destination-cidr-block 10.9.0.0/16 --vpc-peering-connection-id pcx-000000001',
  ];
  function bill(k){
    const natGB=k.internet+(k.endpoint?0:k.s3),crossGB=natGB*Math.max(0,k.azs-k.nats)/k.azs;
    // Explicit aggregate cross-AZ allowance, not a universal AWS transfer quote.
    const cross=crossGB*0.02,fixed=k.nats*(0.045+0.005)*730,processing=natGB*0.045,total=fixed+processing+cross;
    const resilient=k.nats===k.azs,ok=k.s3>=1024&&k.internet>=100&&k.endpoint===1&&resilient&&total<=120;
    return {natGB,crossGB,cross,fixed,processing,total,resilient,ok,saved:k.endpoint?k.s3*0.045:0};
  }
  function Q(q,correct,wrong,answer,explain,domain){const choices=wrong.slice();choices.splice(answer,0,correct);return {q,choices,answer,explain,domain};}
  AG.registerLevels('intermediate',[{
    id:'vpcdeep',icon:'🌐',title:'VPC Deep Dive — private app ka outbound path aur NAT bill',badge:'Network Navin',
    hook:{when:'ShopKaro · demo ke baad national rollout · fictional course story',title:'"S3 images private hain. NAT bill mein images ka charge kyun?"',text:'Ravi ne app private subnets mein shift ki. Priya ka payment verification aur package download outbound internet use karte hain. Neha ne bill dekha: 1,024 GB/month S3 image traffic bhi NAT processing se ja raha tha. Analytics team ki alag VPC orders replica tak nahi pahunch rahi. Private app, cheaper S3 access aur analytics connectivity ko teen separate paths chahiye. Pehle packets ke route decisions click karke dekho.'},
    objectives:['<b>Egress choice</b>: zonal/regional NAT, NAT instance aur IPv6 egress-only gateway compare karo','<b>Endpoints</b>: same-region S3 gateway route vs interface ENI/DNS/SG samjho','<b>Peering</b>: acceptance + both routes, no overlap, no transit','<b>Scale decision</b>: full mesh N×(N−1)/2 vs TGW attachments and segmentation','<b>Debugging</b>: route evidence, Flow Logs aur Reachability Analyzer ke limits pehchano','<b>Hands-on</b>: NAT/EIP, S3 endpoint, two-sided peer repair aur scoped cleanup karo'],
    steps:[
      {q:'Private IPv4 app ko internet kaise milega; inbound webhook ka path alag kyun?',analogy:'Society ke flat ka street entrance band hai, par resident delivery counter se outside order bhej sakta hai. Counter outgoing order ka reply wapas laata hai; stranger counter se naya unsolicited visit start nahi karta.',body:'<div class="tbl-wrap"><table><tr><th>Requirement</th><th>Choice</th><th>Trade-off</th></tr><tr><td>Private IPv4 → payment API</td><td>Public NAT + IGW path</td><td>Managed hours/GB + IPv4 bill</td></tr><tr><td>Custom middlebox/control</td><td>NAT instance</td><td>EC2 patching, source/destination check setting, capacity and failover team owns</td></tr><tr><td>Native IPv6 outbound-only</td><td>Egress-only IGW, ::/0 route</td><td>No address translation; IPv6-only path, network policy still applies</td></tr></table></div>',points:['Zonal public NAT: public subnet + Elastic IP; app default route → NAT; NAT subnet default route → attached IGW. App public IPv4 required nahi.','NAT Gateway ke saath SG attach nahi hota. App SG/NACL, DNS, destination availability aur NAT capacity separately inspect karo.','Payment provider ka unsolicited inbound webhook HTTPS ALB se app tak aata hai. App ka outbound verification request NAT path use karta hai; callback ko NAT inbound mat bolo.'],asli:'Action: lab setup ke baad private app route table dekho. Sirf local route mile toh default internet path absent hai; private label path create nahi karta.'},
      {q:'Zonal NAT aur Regional NAT mein AZ failure ka difference kya hai?',analogy:'Zonal delivery counter ek wing mein hai. Regional service workload ke active wings mein counters manage karti hai. Ek service ID ka matlab one-wing bill nahi.',body:'<div class="tbl-wrap"><table><tr><th>Mode</th><th>Placement/routing</th><th>Decision</th></tr><tr><td>Zonal public NAT</td><td>Public subnet in one AZ; each app AZ uses own NAT</td><td>Explicit same-AZ routes and EIPs; simple lab model</td></tr><tr><td>Regional NAT</td><td>VPC-level regional mode; automatically expands with workload AZ footprint</td><td>Single regional NAT ID; service manages zonal affinity; verify current availability/configuration</td></tr></table></div>',points:['One zonal NAT in AZ-a shared by AZ-b creates an AZ-a failure dependency plus possible cross-AZ transfer charges. NAT available state does not prove a correct IGW route.','Regional NAT exists in current AWS docs; regional mode does not require a public subnet to host the gateway. Charges include each configured AZ-hour and processed GB; one ID is not one AZ-hour.','Exam wording agar zonal public NAT + two AZs specify kare, one NAT per AZ + same-AZ routes choose karo. Current regional alternative ko blanket "all NAT always single-AZ" claim se exclude mat karo.'],asli:'Current simulator/lab deliberately zonal NAT exercise karte hain. Regional expansion and timed AZ failure runtime test nahi hue.'},
      {q:'S3 traffic ko NAT se kaise hataoge; endpoint permission bhi deta hai?',analogy:'Mall warehouse ke liye dedicated goods gate hai. Gate sirf listed warehouse destinations cover karta hai; goods gate badge ke bina stock permission nahi deta.',body:'<p><b>Gateway endpoint</b> S3/DynamoDB ke liye route-table association use karta hai. AWS managed service prefix-list route add karta hai. Matching same-region service prefix route default 0.0.0.0/0 se more specific hoti hai. Arbitrary internet/API aur other-region service traffic automatically endpoint use nahi karte.</p>',points:['Gateway endpoint ka additional hourly/data-processing charge nahi; S3 storage/requests and applicable transfer charges still exist.','Endpoint policy is an extra boundary. IAM role, bucket policy and explicit Deny still evaluate hote hain; endpoint banana GetObject grant ya public access enable nahi karta.','Gateway endpoint ko peering/TGW/VPN ke through generic shared transit gateway mat samjho. Remote/on-prem S3 access ke liye reviewed interface-endpoint design consider karo.','Type: aws ec2 describe-route-tables. DestinationPrefixListId → vpce target dekho; association missing table S3 ko old NAT/default route par bhej sakti hai.'],asli:'Gateway endpoint service-wide private access path hai; private image viewer authorization aur CloudFront origin policy alag boundaries hain.'},
      {q:'Secrets Manager/ECR ke liye gateway route kyun enough nahi?',analogy:'Har specialist shop ka dedicated private service desk chahiye. Ek S3 goods gate se payment, secret store aur container registry ke saare counters nahi milte.',body:'<p><b>Interface endpoint</b> selected AZ subnets mein private ENIs create karta hai. Private DNS enable ho toh supported public service hostname endpoint private IPs par resolve hota hai; VPC DNS support/hostnames and endpoint SG inbound443 required hain.</p>',points:['One interface endpoint can select at most one subnet per AZ. Multiple AZ ENIs resilience/locality improve karte hain; each endpoint/service × AZ ka hourly bill hota hai.','ECR private pull often ecr.api + ecr.dkr interface endpoints and S3 gateway endpoint for image layers needs; logs/other dependencies workload ke hisaab se add karo. Ek endpoint all AWS services cover nahi karta.','Traditional PrivateLink endpoint service mein provider service NLB ke peeche ho sakti hai; consumer interface endpoint starts connections. Service access poora provider network routing nahi hai. New resource/VPC Lattice options ko separately evaluate karo.'],example:'<div class="war-story"><b>Galti jo sab karte hain:</b> PrivateDNS=true dekh ke SDK success assume karna. Endpoint SG443, VPC DNS settings, NACL, IAM and service policy mismatch still call fail kar sakte hain.</div>',asli:'Lab interface endpoint Type=Interface, PrivateDNS=true aur ENIs=2 dikhata hai. Actual DNS lookup or SDK secret retrieval Moto metadata prove nahi karta.'},
      {q:'Analytics VPC orders replica tak kaise pahunchegi?',analogy:'Do societies ka direct connecting gate khul gaya. Dono societies ke road signs update hone chahiye; returning delivery ko bhi correct gate ka route chahiye.',body:'<pre>Analytics: 10.10.0.0/16\n  destination 10.9.0.0/16\n  → active pcx connection\nOrders route table:\n  destination 10.10.0.0/16\n  → same active pcx</pre>',points:['Peering request create + accepter acceptance active connection banata hai. Correct subnet-associated route tables on both sides, SG/NACL ports and application permission still needed.','CIDRs overlap nahi kar sakte. A↔B and B↔C does not create A↔C transit. Another VPC ka NAT, IGW or gateway endpoint peering se automatically share nahi hota.','Same/cross-account and same/cross-region peering possible hain; SG reference and DNS constraints differ. Current simulator same-region topology model karta hai, cross-region rejection AWS limitation nahi.','Example: analytics workers 10.10.1.0/24 only PostgreSQL5432 access to orders reader; broad 0.0.0.0/0 DB permit is not the route fix.'],asli:'Active pcx is one piece of evidence. One-sided route ke saath a successful connection assume mat karo; return table inspect karo.'},
      {q:'Peering mesh kab Transit Gateway hub banega?',analogy:'Har shop ka har shop tak private bridge expensive coordination hai. Common transport hub bridges reduce karta hai; hub ke signs and permitted destinations still configure karne padte hain.',body:'<div class="tbl-wrap"><table><tr><th>Need</th><th>Choice</th><th>Limit/cost</th></tr><tr><td>Few direct VPC connections</td><td>Peering</td><td>Non-transitive; routes/security on both sides</td></tr><tr><td>Many VPCs/on-prem + segmentation</td><td>Transit Gateway</td><td>Attachments, VPC routes and TGW tables/propagation required</td></tr><tr><td>Only shared API, overlapping customer CIDRs</td><td>PrivateLink service endpoint</td><td>Service-scoped access, not full network mesh</td></tr></table></div>',points:['Full mesh N VPCs: N×(N−1)/2 connections. 5 VPCs → 10 peers; 10 VPCs → 45. One TGW hub with 10 VPCs → 10 attachments, plus route/segmentation design.','ShopKaro hypothetical 40-account/120-VPC organization may value central segmentation more than minimizing attachment fees. No claim that every named company runs this topology.','TGW capable of transit does not mean every attached VPC should reach every other VPC. Prod/dev route table association and propagation need deliberate review.'],asli:'Choose by connectivity matrix and operations cost; do not use a universal 5-VPC cutoff. Detailed TGW/hybrid lab Advanced networking mein aayegi.'},
      {q:'Timeout debug karne ke liye logs aur path analyzer kya prove karte hain?',analogy:'Courier tracking delivered address/timing batati hai; city road map planned route batata hai. Tracking entry parcel ke andar ka content nahi dikhati, map real traffic jam test nahi karta.',body:'<div class="tbl-wrap"><table><tr><th>Evidence</th><th>Use</th><th>Limit</th></tr><tr><td>Routes + associations</td><td>Exact source subnet path and return route</td><td>Configured route app/SQL readiness prove nahi</td></tr><tr><td>VPC Flow Logs</td><td>ENI IP/port/ACCEPT/REJECT metadata</td><td>Not packet payload; not every traffic category logged</td></tr><tr><td>Reachability Analyzer</td><td>Static configuration path/blocking component</td><td>Not real packets or application-health test</td></tr></table></div>',points:['Debug order: source/destination/protocol/port name karo → effective source route table → NAT/peer/endpoint state → return route and SG/NACL → DNS/IAM/application evidence.','NAT state available par subnet route local-only ho sakti hai. Route gap ko app code, CPU scaling or world-open SG se hide mat karo.','Flow Logs CloudWatch Logs, S3 or Firehose destination use kar sakte hain; delivery permissions and storage/ingestion cost matter. ACTIVE subscription configuration actual log delivery nahi.'],asli:'Production me kya hota hai: NAT-a ke public route ko edit kar diya, app-a/app-b ke packet timeouts aaye. Available NAT status green rehta hai. Both route hops inspect karo.'},
      {q:'1,024 GB S3/month ka NAT bill kitna bach sakta hai?',analogy:'Dedicated warehouse gate ka fayda delivery-counter per-parcel fee bachana hai. Internet API deliveries ke liye counters abhi bhi required hain; counters ka rent automatically zero nahi hota.',body:'<p>Approx US East list-rate illustration 2025–26; 730 hours/month; ₹88/$1. Zonal NAT ≈ $0.045/hour + $0.045/GB processed; public IPv4 ≈ $0.005/hour. Two NATs + EIPs fixed ≈ 2×($0.045+$0.005)×730 = <b>$73/month</b>. 1,024 GB S3 × $0.045 ≈ <b>$46.08/month ≈ ₹4,055/month</b> processing saving via gateway endpoint. 100 GB internet API traffic still adds ≈ $4.50 NAT processing.</p><p>Interface endpoint example ≈ $0.01 per endpoint/AZ/hour + $0.01/GB first tier: two AZs ≈ $14.60/month fixed per endpoint/service. TGW example ≈ $0.05/VPC attachment/hour + $0.02/GB processed; region/traffic path changes billing.</p>',points:['Planner uses a stated aggregate cross-AZ allowance of $0.02/GB for shared-NAT traffic, not a universal invoice quote. Internet transfer, extra endpoints/logs, storage, taxes and pricing changes excluded.','Correct example: two AZs, two local NATs, S3 endpoint on, S3 1,024 GB and internet100 GB → approximate modeled subtotal $77.50/month = ₹6,820/month.','Small supported-service traffic with existing NAT may not justify many paid interface endpoints. Compliance/private-access requirement and total per-service/AZ cost decide karo.'],asli:'Use gateway endpoint to remove avoidable S3 processing; retain resilient general egress when payment/package internet access is required.'},
    ],
    myth:[{myth:'NAT Gateway always one AZ mein hi operate karta hai',sach:'Zonal NAT AZ-scoped hai; current Regional NAT automatically active workload AZs cover kar sakta hai. Costs/configuration modes differ.'},{myth:'S3 endpoint bana toh IAM GetObject grant mil gaya',sach:'Endpoint route/network path hai; endpoint policy extra boundary hai. IAM/bucket policy and Deny still matter.'},{myth:'Active peering means both VPCs already communicate',sach:'Subnets ke two-sided routes, SG/NACL, DNS and service permission separately required hain.'},{myth:'TGW attach kiya toh prod/dev transit automatically safe hai',sach:'TGW hub routing capable hai; deliberate associations, propagation, VPC routes and segmentation still needed.'}],
    playbook:{title:'Private app ka destination pehle classify karo',use:['Arbitrary IPv4 internet → reviewed public NAT egress path','Same-region S3/DynamoDB from VPC → gateway endpoint','Supported AWS API/private service → interface endpoint, with DNS/SG/policy','Few full-network connections → peering; many networks/hybrid → TGW candidate'],avoid:['NAT ko inbound webhook front door samajhna','Peering se another VPC ka NAT/gateway endpoint transit expect karna','Endpoint count grow karke per-service/AZ fixed bill ignore karna'],how:['Source subnet association aur exact destination route identify karo','Zonal mode mein same-AZ NAT/IGW route; endpoint service prefix vs default compare karo','Peer acceptance plus both routes and least-privilege ports verify karo','Configuration evidence ke baad actual DNS, SDK/app and recovery tests run karo'],redflags:['NAT available par subnet IGW route absent','Endpoint only one app table se associated','One-way peer route; overlapping CIDRs; shared zonal egress','ACTIVE Flow Log subscription ko delivered packet proof bolna'],rule:'Decision tree: arbitrary internet? NAT. Same-region S3/DynamoDB? gateway endpoint. Supported service private API? interface endpoint. Full VPC network? peering/TGW with deliberate two-sided routes.'},
    exam:[{cue:'"private IPv4 instances need internet"',pick:'Public NAT path',why:'Private default route → NAT, NAT subnet → IGW; public NAT uses EIP.'},{cue:'"two AZs; zonal NAT; resilient egress"',pick:'One zonal NAT per AZ and local routes',why:'Shared failed NAT AZ should not break surviving AZ.'},{cue:'"NAT cost mostly same-region S3"',pick:'Gateway endpoint on correct route tables',why:'No added endpoint hourly/processing charge for that path.'},{cue:'"private Secrets Manager/SQS calls"',pick:'Interface endpoint',why:'Private ENI + DNS + SG443 + IAM/service policy.'},{cue:'"A–B and B–C peered, A–C required"',pick:'Direct A–C peer or reviewed transit hub',why:'Peering is non-transitive.'},{cue:'"VPC CIDRs overlap"',pick:'Cannot peer directly',why:'Renumber or evaluate service-level PrivateLink where appropriate.'},{cue:'"native IPv6 outbound-only"',pick:'Egress-only IGW',why:'IPv6 route ::/0; no unsolicited inbound connections.'},{cue:'"who connected/rejected at ENI"',pick:'VPC Flow Logs',why:'IP flow metadata, not full payload/application trace.'},{cue:'"Regional NAT mode"',pick:'Automatic workload-AZ expansion; per-AZ billing',why:'Current option; do not assume one service ID equals one zonal hourly charge.'}],
    stages:[
      {type:'dryrun',title:'🔍 S3 bill ka route aur analytics ka return path',goal:'Agla step par one routing change dekho. Service prefix versus default route aur missing return route ke two questions answer karo.',nodes:[N('ec2',130,95,{label:'private app'}),N('rt',390,95),N('s3',780,95),N('nat',350,270,{label:'zonal NAT-a'}),N('igw',610,270),N('internet',880,270,{label:'Payment API'}),N('ec2#analytics',140,435,{label:'analytics'}),N('pcx',450,435),N('rds',780,435,{label:'orders reader'})],groups:[{label:'App subnet',x:20,y:30,w:220,h:115,kind:'private'},{label:'Public NAT subnet',x:240,y:205,w:220,h:115,kind:'public'},{label:'Analytics VPC',x:20,y:365,w:240,h:145,kind:'vpc'},{label:'Orders subnet',x:660,y:365,w:290,h:145,kind:'private'}],edges:[{from:'ec2',to:'rt'},{from:'rt',to:'s3',dashed:true},{from:'rt',to:'nat'},{from:'nat',to:'igw'},{from:'igw',to:'internet'},{from:'igw',to:'s3',dashed:true},{from:'ec2#analytics',to:'pcx'},{from:'pcx',to:'rds'}],panels:[{id:'cost',title:'Route / NAT subtotal'},{id:'peer',title:'Analytics / return route'}],steps:[
        {clock:'before',say:'App route table sirf local + default NAT route use karti hai. Matching S3 image traffic bhi NAT se ja raha hai; per-GB processing meter tick karta hai.',flows:[{from:'ec2',to:'rt',tone:'ok'},{from:'rt',to:'nat',label:'0.0.0.0/0',tone:'slow'},{from:'nat',to:'igw',tone:'slow'},{from:'igw',to:'s3',tone:'slow'}],panels:{cost:['1,024 GB S3/month × approx $0.045/GB','$46.08/month avoidable NAT processing'],peer:['Analytics/ShopKaro peer not yet accepted']}},
        {clock:'endpoint',say:'Gateway endpoint app route table se associate hua. AWS same-region S3 managed prefix-list route add karta hai; default NAT route general internet ke liye rehta hai.',flows:[{from:'rt',to:'s3',label:'S3 service prefix',tone:'ok'}],ask:{q:'S3 service prefix aur default route dono match karte hain. Kaunsa path?',choices:['More-specific S3 prefix-list route endpoint ko choose karti hai','First-created default route wins because table order defines priority','NAT route wins because NAT has an Elastic IP address','Both routes duplicate every request to increase availability'],answer:0,explain:'Routing longest-prefix rules use karti hai; row order/EIP route priority nahi. Matching more-specific service route default ko beat karti hai; requests duplicate nahi hote.'},panels:{cost:['S3 NAT processing avoided on associated app table','Endpoint route does not grant S3 IAM permission']}},
        {clock:'payment',say:'Payment provider arbitrary internet destination hai; S3 prefix match nahi. Payment verification still default NAT → IGW use karti hai. Incoming provider webhook public ALB ka separate inbound path hai.',flows:[{from:'rt',to:'nat',tone:'ok'},{from:'nat',to:'igw',tone:'ok'},{from:'igw',to:'internet',tone:'ok'}],panels:{cost:['S3 shortcut does not replace general egress','NAT fixed hourly + API GB charges remain']}},
        {clock:'peer accepted',say:'Peering active hua. Analytics table mein 10.9.0.0/16 → pcx route hai, par orders table mein analytics return route absent hai. SG5432 already correct hai; active pcx alone enough nahi.',nodes:{pcx:{tone:'ok',badge:'active'}},flows:[{from:'ec2#analytics',to:'pcx',tone:'slow'},{from:'pcx',to:'rds',tone:'slow'}],panels:{peer:['Analytics outbound route present','Orders return route 10.10.0.0/16 absent']},ask:{q:'Connection timeout ka most direct repair?',choices:['Orders subnet-associated table mein analytics CIDR route to same active peer add karo','DB inbound5432 world-open karo; return route automatically appear hogi','Another S3 gateway endpoint create karo; PostgreSQL follows S3 prefixes','NAT EIP ko analytics DNS name de do; peering becomes transitive'],answer:0,explain:'Reply path needs peer route in orders effective table. Broad ingress does not create routes; S3 endpoint and EIP/DNS do not route PostgreSQL or add transit.'}},
        {clock:'return fixed',say:'Orders table mein 10.10.0.0/16 → active pcx route add hua. Correct two-sided routes plus existing SG/NACL/DB permissions configured path complete karte hain. Actual SQL/DNS tests still required hain.',flows:[{from:'rds',to:'pcx',label:'reply route',tone:'ok'},{from:'pcx',to:'ec2#analytics',tone:'ok'}],panels:{peer:['Both subnet-associated route tables correct','No CIDR overlap; no accidental transit']}},
        {clock:'review',say:'Three independent decisions: arbitrary internet via NAT, matching same-region S3 via gateway endpoint, analytics via direct peer and both routes. Regional NAT and TGW solve different operational problems; names ko interchangeable mat samjho.',panels:{cost:['Remove avoidable processing, preserve required resilience'],peer:['Configuration review first; real packet/app tests after']}},
      ],lesson:'More-specific route destination decide karti hai. Active resource status, network permission aur application success alag evidence hain.'},
      {type:'flowlab',title:'🎛️ NAT bill board — S3 shortcut ke saath AZ resilience',goal:'At least 1,024 GB/month S3 aur 100 GB/month internet serve karo. One zonal NAT per active AZ, S3 endpoint on, modeled subtotal ≤approx $120/month rakho. Demand kam karke goal bypass nahi hoga.',scenario:'730 hours/month; ₹88/$1; approximate US East 2025–26 NAT $0.045/hour + $0.045/GB, IPv4 $0.005/hour. Uniform workload across AZs assumed. Shared-NAT cross-AZ allowance $0.02/GB aggregate is an explicit budgeting assumption, not universal billing. Storage/requests/logs/interface endpoints/internet transfer/taxes extra.',knobs:[{id:'s3',label:'S3 traffic',min:512,max:2048,step:512,value:1024,unit:' GB/month'},{id:'internet',label:'Internet APIs/packages',min:50,max:200,step:50,value:100,unit:' GB/month'},{id:'azs',label:'Active AZs',min:2,max:3,step:1,value:2},{id:'nats',label:'Zonal NAT count',min:1,max:3,step:1,value:1},{id:'endpoint',label:'S3 gateway endpoint',min:0,max:1,step:1,value:0,labels:{0:'Off / S3 via NAT',1:'On / both app tables'}}],model:k=>{const b=bill(k);return {readouts:[{label:'Approx monthly subtotal',value:'$'+b.total.toFixed(2)+' · ₹'+Math.round(b.total*88),tone:b.total<=120?'ok':'bad'},{label:'NAT fixed / processing',value:'$'+b.fixed.toFixed(2)+' / $'+b.processing.toFixed(2)+' per month',tone:'info'},{label:'Cross-AZ allowance',value:b.crossGB.toFixed(0)+' GB · $'+b.cross.toFixed(2)+'/month',tone:b.crossGB===0?'ok':'warn'},{label:'Avoided S3 NAT processing',value:'$'+b.saved.toFixed(2)+'/month',tone:k.endpoint?'ok':'bad'},{label:'AZ-loss dependency',value:b.resilient?'Independent same-AZ zonal NAT routes assumed':'Missing/excess NAT count for one-per-AZ design',tone:b.resilient?'ok':'bad'}],verdict:{ok:b.ok,text:b.ok?'Fixed traffic, per-AZ egress and endpoint goals pass modeled subtotal. Verify real routes, failure behavior and full bill separately.':'Keep S3≥1,024 GB/month, internet≥100 GB/month; set NAT count=AZ count and endpoint On. Example 2 AZs/2 NATs gives approx $77.50/month at default traffic.'}};},check:k=>bill(k).ok,lesson:'Example 1,024 GB S3, 100 GB internet, 2 AZs, 2 NATs, endpoint On → fixed $73 + API processing $4.50 = approx $77.50/month (₹6,820/month). Same NAT count without endpoint adds approx $46.08 S3 processing.'},
      {type:'bins',title:'🧭 Destination → correct path',instructions:'Current requirement se choose karo; NAT, endpoint aur full-network connectivity alag jobs hain.',bins:[{id:'nat',label:'Public NAT'},{id:'gateway',label:'Gateway endpoint'},{id:'interface',label:'Interface endpoint'},{id:'peer',label:'Peering'},{id:'tgw',label:'Transit Gateway'}],items:[{text:'Private IPv4 app → arbitrary payment HTTPS API',bin:'nat',explain:'General outbound IPv4 internet; webhook inbound ALB se alag.'},{text:'Same-region S3 image access from own VPC',bin:'gateway',explain:'Service prefix route; no additional gateway endpoint hourly/processing charge.'},{text:'Secrets Manager via private AWS service ENI',bin:'interface',explain:'PrivateLink endpoint, DNS/SG/IAM still required.'},{text:'Two non-overlapping VPCs; direct private network routes',bin:'peer',explain:'Few direct connections; both routes and security needed.'},{text:'120 VPCs/hybrid with controlled transit segments',bin:'tgw',explain:'Hub attachments and deliberate route table segmentation.'},{text:'Private ECR API endpoint and registry endpoint',bin:'interface',explain:'ecr.api/ecr.dkr plus S3 gateway for image layers; dependencies vary.'}]},
      {type:'order',title:'🧱 Zonal public NAT path ka build order',instructions:'Existing VPC/IGW ke saath deterministic construction order rakho; public routing aur readiness ko verify karo.',steps:[{text:'Public subnet route table ko IGW default route ke saath associate/verify karo',explain:'NAT subnet ka internet hop pehle explicit hona chahiye; public label enough nahi.'},{text:'VPC Elastic IP allocate karo',explain:'Public zonal NAT requires an allocation ID; each AZ has independent allocation.'},{text:'Public subnet mein allocation ID se NAT create karo',explain:'NAT belongs to selected AZ; app private subnet ko NAT hosting subnet mat samjho.'},{text:'NAT available waiter/state verify karo',explain:'Pending resource ko usable serving path assume mat karo; real provisioning asynchronous hai.'},{text:'Same-AZ private app table ka default route NAT ko point karo',explain:'Private app outbound matches default; local AZ target avoids shared zonal dependency.'},{text:'Actual DNS/HTTPS access aur failure path test karo',explain:'Configured route and available metadata real destination/application success prove nahi karte.'}],explain:'API NAT creation route correctness prove nahi karti. Waiter metadata available hone ke baad app route install karo; final runtime test actual egress prove karta hai.'},
      {type:'triage',title:'🩺 NAT available hai, packages download kyun nahi?',symptom:'Private app ka package HTTPS timeout hai. App table NAT ko route karti hai; NAT State=available. NAT subnet ka effective route table inspect karo. Evidence is a teaching fixture, not Moto packet measurement.',commands:[{cmd:'aws ec2 describe-nat-gateways --nat-gateway-ids nat-bad',out:'{"NatGateways":[{"NatGatewayId":"nat-bad","SubnetId":"subnet-wrong","State":"available","ConnectivityType":"public"}]}',clue:true,note:'Available NAT metadata; subnet-wrong route association still unknown.'},{cmd:'aws ec2 describe-route-tables --filters Name=association.subnet-id,Values=subnet-wrong',out:'{"RouteTables":[{"RouteTableId":"rtb-isolated","Routes":[{"DestinationCidrBlock":"10.9.0.0/16","GatewayId":"local"}]}]}',clue:true,note:'NAT subnet has no IGW default route. Public NAT in isolated subnet cannot reach IPv4 internet through IGW.'},{cmd:'aws ec2 describe-route-tables --route-table-ids rtb-app-a',out:'{"RouteTables":[{"Routes":[{"DestinationCidrBlock":"0.0.0.0/0","NatGatewayId":"nat-bad","State":"active"}]}]}',clue:false,note:'First route hop exists; next hop subnet routing is broken.'},{cmd:'aws ec2 describe-security-groups --group-ids sg-app',out:'{"SecurityGroups":[{"IpPermissionsEgress":[{"IpProtocol":"tcp","FromPort":443,"ToPort":443,"IpRanges":[{"CidrIp":"0.0.0.0/0"}]}]}]}',clue:false,note:'HTTPS outbound allowed. NACL and DNS also verified in this fixture; permit is not a missing route.'}],questions:[Q('Which evidence explains the strongest path gap?','NAT subnet effective table lacks 0.0.0.0/0 to attached IGW',['NAT available status guarantees network path so app CPU is the cause','App default route present means NAT subnet table cannot affect egress','No public IPv4 on app means NAT requires assigning a public app EIP'],1,'Public NAT needs its own subnet IGW route. Available is resource state; app hop alone incomplete; app public IPv4 is unnecessary for NAT egress.','resilient'),Q('A repair preserving private app and expected topology?','Place replacement zonal NAT in correct public subnet and update same-AZ app route',['Move app to public subnet and add broad inbound access for package downloads','Add S3 gateway endpoint and assume all external package registries use S3 route','Change DB SG inbound5432 source so HTTPS return route is automatically created'],2,'Correct public NAT/IGW topology repairs the path; alternatively fix intended NAT-subnet association after reviewing exposure. Public app bypass changes security design; S3 endpoint does not cover arbitrary hosts; DB SG does not create routes.','resilient')]},
      (function(){const tasks=[{text:'AZ-a app → available public NAT-a with allocated EIP → IGW',check:s=>natOK(s,'a')},{text:'AZ-b app → independent available public NAT-b/EIP → IGW',check:s=>natOK(s,'b')},{text:'Same-region S3 gateway endpoint has managed prefix routes on both app tables',check:endpointOK},{text:'Active non-overlapping peer; orders and analytics effective tables have both routes',check:peerOK},{text:'Original private apps/reader, scoped DB5432 and local routes preserved',check:preserved},{text:'Only planned resources: 2 live NATs / 2 EIPs / 1 live S3 endpoint / 1 live peer',check:s=>(s.account.natGateways||[]).filter(n=>n.state!=='deleted').length===2&&(s.account.addresses||[]).length===2&&(s.account.vpcEndpoints||[]).filter(e=>e.state!=='deleted').length===1&&(s.account.vpcPeerings||[]).filter(p=>p.state!=='deleted').length===1}];return {type:'terminal',title:'🖥️ Mission — egress, S3 cost path aur analytics peer',instructions:'Fresh mission state mein IDs deterministic hain. allocate-address ke two IDs eipalloc-000000001/2, new NAT IDs nat-000000001/2 aur peer pcx-000000001 milenge. Read output, wait for available, then route. Thirteen intended actions hints mein runnable hain.',goal:'Two public subnet NATs with independent EIPs + waiters; rtb-app-a/b default routes to own AZ NAT. S3 Gateway endpoint both app tables par. vpc-shop↔vpc-analytics peer create + accept; rtb-orders analytics CIDR return route and rtb-analytics ShopKaro CIDR route. Only planned 2 NATs/2 EIPs/1 S3 endpoint/1 peer rakho; original resources/permissions preserve karo. Simulator transitions immediate metadata hain; real packet tests separate hain.',account:seed(),tasks,solution:SOLUTION.slice(),success:AG.allOf(tasks),hints:SOLUTION.map((c,i)=>c+[' — first zonal NAT ka IPv4 allocation',' — second AZ ka independent IPv4 allocation',' — public-a subnet choose karo, private app subnet nahi',' — pending NAT route usable hone se pehle availability wait',' — public-b + second allocation',' — second NAT availability wait',' — app-a effective table',' — app-b own AZ NAT, shared NAT-a shortcut nahi',' — route associations generate S3 prefix routes automatically',' — non-overlapping VPCs ka request',' — accepter activation; routes separately needed',' — reply path from orders subnet',' — analytics outbound path; final state now complete'][i]),successText:'Two independent zonal egress paths, S3 service route and active two-sided peer configuration repaired. Original reader/apps scoped/private hain. Runtime DNS, packets, SQL access, AZ recovery and full billing still need real tests.'};})(),
      {type:'docker',title:'🐳 Real lab — NAT, gateway/interface endpoints aur peering',project:'09-nat-endpoint-peering',goal:'README ex1–ex5 follow karo: setup inspect → real scripts build → endpoint association remove/repair → peer/flow subscription inspect → scoped cleanup.',why:'Actual AWS CLI/Moto APIs metadata persist karte hain. No OS/app/SQL/packet/DNS runtime; no false real-connectivity claim.',steps:[{text:'README Setup exports, then ex1 setup. Local-only app route inspect karo.',cmd:'cd aws-gurukul/docker-labs\n./start-moto.sh\nsource env.sh\ncd 09-nat-endpoint-peering\n# README Setup exports isi terminal mein run karo.\nbash setup.sh\nsource .lab/resources.sh',expect:'Starting state: private app tables local-only; no NAT, endpoint or peer.'},{text:'ex2: scripts read karke run karo; two interface ENIs and private DNS metadata inspect karo.',cmd:'bash exercises.sh\nsource .lab/resources.sh',expect:'{"Type":"Interface","State":"available","PrivateDNS":true,"ENIs":2}'},{text:'ex3: endpoint route table association remove/add; count1 then2 expect karo.',cmd:'aws ec2 modify-vpc-endpoint --vpc-endpoint-id "$ENDPOINT" --remove-route-table-ids "$APP_RT_B"\naws ec2 modify-vpc-endpoint --vpc-endpoint-id "$ENDPOINT" --add-route-table-ids "$APP_RT_B"',expect:'{"Return":true}'},{text:'ex4 metadata review; ex5 cleanup. Deleted endpoint tombstones current Moto mein retained hain.',cmd:'aws ec2 describe-flow-logs --flow-log-ids "$FLOW" --query \'FlowLogs[0].{State:FlowLogStatus,Traffic:TrafficType,Destination:LogDestinationType}\'\nbash cleanup.sh',expect:'{"State":"ACTIVE","Traffic":"ALL","Destination":"s3"}'}],observe:Q('Gateway endpoint route present aur FlowLogStatus ACTIVE. What is actually verified?','Expected route/subscription metadata; real packets and delivered logs remain untested',['S3 application IAM access and invoice authorization are automatically granted','NAT throughput and multi-AZ recovery time were measured by describe commands','FlowLogStatus ACTIVE proves every expected packet reached the destination app'],3,'API config is real metadata evidence. Endpoint does not grant application access; describes do not load-test/failover-test; ACTIVE subscription does not prove delivered packets/log records.','resilient')},
      {type:'quiz',bonus:true,title:'📝 SAA-style VPC decisions',questions:[
        Q('Same-region S3 is most of NAT processing bill. Lowest extra path cost?','Gateway endpoint for matching S3 traffic on all relevant app route tables',['Interface endpoints for every S3 request while keeping identical route design','A larger NAT gateway IP pool because more addresses remove per-GB charges','Public app EIPs so private S3 IAM role and endpoint policies can be omitted'],0,'Gateway path avoids NAT processing with no added gateway endpoint hourly/GB charge. Paid S3 interface path may fit remote-access requirements; more EIPs do not remove processing; public addressing does not replace IAM.','cost-optimized'),
        Q('Private EC2 needs native IPv6 outbound, no unsolicited IPv6 inbound. Pick?','Egress-only internet gateway with correct private-subnet ::/0 route',['IPv4 public NAT alone without DNS64/NAT64 or IPv6 routing changes','S3 gateway endpoint so every IPv6 internet destination matches S3 prefix','Direct public IGW route and assume route table blocks inbound sessions'],1,'Egress-only IGW is native IPv6 outbound-only. IPv4-only topology incomplete; S3 prefix is service-specific; ordinary IGW route is not the egress-only restriction.','secure'),
        Q('VPC A–B and B–C peers exist. App in A needs C. Correct next design?','Direct A–C peer with routes/security, or a deliberately configured transit hub',['Add a second identical A–B peer so traffic becomes transitively routed','Route A→C using the existing B–C peer ID although A is not a participant','Raise A NAT gateway count so existing peering inherits transit capability'],2,'Peering cannot forward transit through B; a direct peer or reviewed hub is needed. Duplicate link/NAT count does not add transit, and nonparticipant route targets are invalid.','resilient'),
        Q('Interface endpoint PrivateDNS enabled, SDK times out. Next direct network evidence?','Endpoint ENI SG443, VPC DNS attributes, source routes/NACL and resolved addresses',['Only IAM policy length because any API authorization failure must cause TCP timeout','Only S3 bucket encryption because endpoint private IP comes from the bucket key','Only EC2 public IP assignment because interface endpoints require public clients'],3,'DNS/SG/NACL/ENI evidence localizes timeout; IAM denial usually has service error once reachable, not mandatory timeout. Bucket encryption/public IPv4 unrelated to private endpoint connectivity.','high-performing'),
        Q('5 VPCs require full direct mesh. Connections count and trade-off?','10 peers; non-transitive routes/security; compare TGW central operations and cost',['25 peers; square growth means every VPC must peer with itself for routing','5 peers; one link per VPC automatically provides full transitive access','20 peers; requester and accepter halves are separate billed connections'],0,'N(N−1)/2=10 undirected peers. No self-links or separately counted accepter half; five hub attachments can provide transit only with configured hub routing.','cost-optimized'),
        Q('Analytics peer active; forward route exists; DB return table lacks analytics route. Fix?','Add analytics reply CIDR route to the same peer in orders effective table',['Add another world-open DB SG rule so routing is inferred from permitted source','Change S3 endpoint private DNS so PostgreSQL packets get a managed S3 prefix','Create another NAT in analytics VPC because accepted peering uses public EIPs'],1,'Two-sided private paths needed. SG allow does not create route; S3 DNS/prefix is not PostgreSQL routing; peering does not need NAT/public EIPs.','resilient'),
        Q('Regional NAT uses one gateway ID across workload AZs. Billing inference?','Review configured AZ-hours and processed GB; one ID is not one AZ charge',['One regional gateway ID bills one zonal hourly fee even across multiple active AZs','Regional mode removes all NAT processing charges because AWS manages routing','Regional mode replaces every private service IAM policy and public IPv4 cost'],2,'Regional NAT pricing is per configured AZ-hour plus processing and other applicable charges. Managed routing does not remove GB/IAM/public-address considerations.','cost-optimized'),
        Q('Reachability Analyzer says configuration path reachable. What still needs runtime test?','Actual application listener, DNS/SDK behavior, authorization and response correctness',['Whether every modeled route and SG rule exists, because analyzer uses real packets','Whether packet payload is visible, because analyzer captures every application body','Whether ASG automatically grants database permissions to every attached ENI'],3,'Analyzer evaluates configuration, not actual packets or application payload/health. App/DNS/auth/data tests remain separate; ASG does not grant DB credentials.','high-performing'),
      ]},
    ],
    interview:{title:'🎤 Network review follow-ups',instructions:'Destination, permissions, failure path aur bill explain karo; slogans ke bajay evidence choose karo.',questions:[
      Q('Both app AZs use NAT-a. Requirement is survive AZ-a loss. Best zonal design?','Own public NAT/EIP and default route in every active AZ; verify dependencies',['Keep one NAT-a but raise its EIP count to move its deployment to multiple AZs','Move both workers to private-a so egress routes are identical during AZ loss','Use the active analytics peer to borrow another VPC IGW without added design'],0,'Zonal NAT location is a shared AZ dependency. More EIPs do not change mode; consolidating workers worsens resilience; peering does not expose another IGW as transit.','resilient'),
      Q('An interface endpoint per service in 3 AZs, 5 services. Fixed-cost input?','15 endpoint-AZ hours per clock hour, plus data and applicable regional charges',['One endpoint hourly fee because all five services share the same VPC ID','Three total endpoint hours because selected AZ count overrides service count','Five total endpoint hours because private DNS removes the per-AZ component'],1,'Endpoint/service × selected AZ is the basic fixed-hour multiplier. VPC ID/private DNS do not merge service endpoints; exact service/region pricing still verify.','cost-optimized'),
      Q('Hundreds of customer VPCs overlap CIDRs; expose only one internal API. Candidate?','Service-level PrivateLink endpoint design with scoped provider/consumer permissions',['Full peering mesh with identical CIDRs because different account IDs disambiguate routes','TGW full-network routing without CIDR planning because attachments renumber clients','Internet-facing NAT gateways accepting inbound consumer connections on custom ports'],2,'PrivateLink scopes service access and can fit overlapping customer networks. Peering cannot overlap; TGW does not simply renumber CIDRs; NAT is not a public inbound API front door.','secure'),
      Q('Flow Log metadata REJECT at an ENI. What does the record establish?','Observed IP-flow rejection metadata; inspect SG/NACL and correlate the path',['Application HTTP response body rejected payment authorization for that customer','Every route is correct because records can only exist for successful sessions','The packet payload includes the exact SQL query that failed database validation'],3,'Flow metadata records addresses/ports/action, not application payload or SQL/HTTP business reason. Route and firewall evidence still need correlation.','secure'),
      {terminal:(function(){const a=seed();a.vpcEndpoints=[{id:'vpce-s3-existing',type:'Gateway',vpcId:'vpc-shop',serviceName:'com.amazonaws.ap-south-1.s3',state:'available',prefixListId:'pl-s3',routeTableIds:['rtb-app-a']}];a.routeTables.find(t=>t.id==='rtb-app-a').routes.push({prefixListId:'pl-s3',target:'vpce-s3-existing',type:'endpoint',managed:true,state:'active'});const tasks=[{text:'Existing S3 endpoint repaired on app-a and app-b with both managed prefix routes',check:endpointOK},{text:'VPC ALL Flow Log subscription targets existing private shop-flowlogs bucket',check:s=>(s.account.flowLogs||[]).some(f=>f.resourceId==='vpc-shop'&&f.trafficType==='ALL'&&f.state==='ACTIVE'&&f.destinationType==='s3'&&f.destination==='arn:aws:s3:::shop-flowlogs')},{text:'Original reader/apps/routes preserved; no duplicate S3 endpoint',check:s=>preserved(s)&&(s.account.vpcEndpoints||[]).filter(e=>e.state!=='deleted').length===1}];const solution=['aws ec2 modify-vpc-endpoint --vpc-endpoint-id vpce-s3-existing --add-route-table-ids rtb-app-b','aws ec2 create-flow-logs --resource-type VPC --resource-ids vpc-shop --traffic-type ALL --log-destination-type s3 --log-destination arn:aws:s3:::shop-flowlogs'];return {title:'🖥️ Repair existing endpoint + configure diagnostic metadata',goal:'Existing vpce-s3-existing ko rtb-app-b se bhi associate karo; recreate mat karo. vpc-shop ke ALL flow metadata ka S3 destination arn:aws:s3:::shop-flowlogs configure karo. No actual packet/log delivery claim.',account:a,tasks,success:AG.allOf(tasks),hints:solution.slice(),solution,successText:'Existing endpoint association and diagnostic subscription metadata ready. Real destination permissions, delivered log objects and packet tests still need verification.'};})()},
    ]},
    success:['NAT, gateway/interface endpoint aur peer ka job separately choose kar sakta hoon','Zonal vs Regional NAT aur explicit cost/resilience assumptions explain kar sakta hoon','Both route directions and effective subnet associations inspect/repair kar sakta hoon','Configuration metadata ko actual network/app proof se distinguish kar sakta hoon'],
    homework:'<p><b>Optional, approved real AWS sandbox only; billable:</b> current regional NAT/IPv4/endpoint/transfer/log prices estimate karo. Per-AZ zonal NAT route or reviewed Regional NAT choose karo. Private app se approved HTTPS destination test karo; S3 gateway route and IAM access compare karo; overlapping CIDR avoid karke peer and both routes create karo. Endpoint/Flow Log delivery permissions review karke actual SDK/SQL and log objects inspect karo. Avoid real sensitive DB access. Cleanup: endpoint associations/endpoints, Flow Log subscriptions/destination objects, peering routes/peer, NAT + deleted waiter, EIPs, test instances, SGs/subnets/route tables/IGW/VPC delete karo. NAT deletion EIP release nahi hai. Existing artifacts/shared resources ko reset mat karo.</p>',
    cards:[{front:'Zonal public NAT ke two routing hops?',back:'App default route → same-AZ NAT; NAT subnet default route → attached IGW. Public NAT EIP uses; private app public IPv4 unnecessary.'},{front:'Regional NAT means one AZ fee?',back:'Nahi. Regional mode workload AZ footprint follow karta hai; configured AZ-hours and processed GB billed hote hain. Zonal placement rules separately apply.'},{front:'S3 gateway endpoint vs interface endpoint?',back:'Gateway route-table service prefix for same-region S3/DynamoDB, no added endpoint hourly/GB fee. Interface private ENIs for supported service; per-service/AZ hours and data cost.'},{front:'Endpoint policy kya grant karti hai?',back:'Endpoint policy extra boundary hai. IAM/bucket policy/Deny still evaluate hote hain; route alone GetObject grant nahi.'},{front:'Peering active, timeout: kya inspect?',back:'Source effective table, return effective table, SG/NACL, DNS and app. Peering acceptance does not install both routes automatically.'},{front:'Full mesh formula?',back:'N×(N−1)/2 peers: 5→10;10→45. TGW N attachments reduces mesh management, but explicit routes/segmentation and cost matter.'},{front:'Flow Logs vs Reachability Analyzer?',back:'Flow Logs observed IP-flow metadata, no payload. Reachability Analyzer static configured path analysis, no real packet/app-health test.'},{front:'S3 1,024 GB NAT saving?',back:'At approx $0.045/GB, $46.08/month processing avoided via matching gateway endpoint. Required NAT fixed hours and other internet traffic costs remain.'}],
  }]);
})();
